import { useEffect, useState, type FormEvent, type ReactNode } from 'react';
import { ArrowUpRight, ArrowRight, Plus, Search, LayoutDashboard, Layers, Users, MessageSquare, GraduationCap, Shield, Sparkles, Sun, Moon, Menu, X, Check, Target, Clock, ChevronRight, Link, Copy, CheckCircle2, Circle, LogOut, Settings, Flag, Radio, FileText, ListTodo, Lock, Globe, Zap, Code2, Trash2 } from 'lucide-react';
import { loadState, seed, storageKey, uid, submitApplication, personFromApplication, invitationStatus, canManage, canEnter, reviewProject, safeUrl, type State, type Project, type Person, type Application } from './domain';

type Page = 'home' | 'projects' | 'challenges' | 'community' | 'learning' | 'members' | 'invites' | 'admin' | 'profile';
type Modal = { kind: string; id?: string } | null;
type Field = { name: string; label: string; type?: string; placeholder?: string; value?: string | number; required?: boolean; options?: { value: string; label: string }[]; min?: number; max?: number };
export default function App() {
  const [data, setData] = useState<State>(loadState);
  const [actor, setActor] = useState('you');
  const [page, setPage] = useState<Page>('home');
  const [projectId, setProjectId] = useState<string | null>(null);
  const [tab, setTab] = useState('overview');
  const [channel, setChannel] = useState('general');
  const [lang, setLang] = useState<'es' | 'en'>(() => localStorage.getItem('nextone.lang') === 'en' ? 'en' : 'es');
  const [theme, setTheme] = useState(() => localStorage.getItem('nextone.theme') || 'dark');
  const [accent, setAccent] = useState(() => localStorage.getItem('nextone.accent') || 'violet');
  const [search, setSearch] = useState('');
  const [mobile, setMobile] = useState(false);
  const [modal, setModal] = useState<Modal>(null);
  const [notice, setNotice] = useState('');
  const [persistenceError, setPersistenceError] = useState(false);
  const [assistant, setAssistant] = useState({ title: '', summary: '', difference: '' });
  const [assistantResult, setAssistantResult] = useState(false);
  const [admission, setAdmission] = useState('');
  const tr = (es: string, en: string) => lang === 'es' ? es : en;
  const me = data.people.find(p => p.id === actor);
  const isVisitor = actor === 'visitor';
  const isFounder = me?.role === 'founder';
  const isMentor = me?.role === 'mentor';
  const enabled = !!me && me.status === 'active';
  const project = data.projects.find(p => p.id === projectId);
  const memberOf = project && canEnter(project, me);
  const manages = project && enabled && canManage(project, me);
  const name = (id: string) => data.people.find(p => p.id === id)?.name || tr('Participante', 'Participant');
  const initials = (value: string) => value.split(' ').slice(0,2).map(w => w[0]).join('');
  const toast = (text: string) => setNotice(text);
  useEffect(() => { try { localStorage.setItem(storageKey, JSON.stringify(data)); setPersistenceError(false); } catch { setPersistenceError(true); } }, [data]);
  useEffect(() => { document.documentElement.lang = lang; localStorage.setItem('nextone.lang', lang); }, [lang]);
  useEffect(() => { document.documentElement.dataset.theme = theme; localStorage.setItem('nextone.theme', theme); }, [theme]);
  useEffect(() => { document.documentElement.dataset.accent = accent; localStorage.setItem('nextone.accent', accent); }, [accent]);
  useEffect(() => { if (!notice) return; const timer = setTimeout(() => setNotice(''), 5000); return () => clearTimeout(timer); }, [notice]);
  useEffect(() => { const code = new URLSearchParams(location.search).get('invite'); if (code) { setActor('visitor'); setModal({ kind: 'apply', id: code }); } }, []);
  useEffect(() => { if (!modal) return; const close = (e: KeyboardEvent) => { if (e.key === 'Escape') setModal(null); }; window.addEventListener('keydown', close); return () => window.removeEventListener('keydown', close); }, [modal]);
  function navigate(next: Page) { setPage(next); setProjectId(null); setSearch(''); setMobile(false); }
  function openProject(id: string) { setProjectId(id); setPage('projects'); setTab('overview'); setChannel('general'); setSearch(''); }
  function open(kind: string, id?: string) { setModal({ kind, id }); setAssistantResult(false); setAssistant({ title: '', summary: '', difference: '' }); setAdmission(''); }
  function patchProject(id: string, fn: (p: Project) => Project) { setData(d => ({ ...d, projects: d.projects.map(p => p.id === id ? fn(p) : p) })); }
  function log(text: string) { setData(d => ({ ...d, log: [`${new Date().toISOString()} · ${text}`, ...d.log] })); }
  function toggleTask(p: Project, id: string) { if (!canEnter(p, me) || !enabled) return; patchProject(p.id, x => ({ ...x, tasks: x.tasks.map(t => t.id === id ? { ...t, status: t.status === 'todo' ? 'doing' : t.status === 'doing' ? 'done' : 'todo' } : t) })); }
  function join(p: Project) { if (!enabled || p.members.includes(actor) || p.requests.includes(actor)) return; patchProject(p.id, x => ({ ...x, requests: [...x.requests, actor] })); toast(tr('Solicitud enviada al líder del proyecto.', 'Request sent to the project leader.')); }
  function approveMember(p: Project, id: string) { if (!canManage(p, me) || !enabled) return; if (p.members.length >= p.capacity) return toast(tr('El equipo alcanzó su cupo.', 'The team is full.')); if (data.people.find(x => x.id === id)?.status !== 'active') return toast(tr('El usuario está suspendido.', 'The user is suspended.')); patchProject(p.id, x => ({ ...x, members: [...new Set([...x.members, id])], requests: x.requests.filter(i => i !== id) })); log(`Ingreso aprobado: ${name(id)} / ${p.title}`); }
  function decideApplication(id: string, approve: boolean) { if (!isFounder) return; const a = data.applications.find(x => x.id === id); if (!a || a.state !== 'pending') return; const memberId = uid(); setData(d => ({ ...d, applications: d.applications.map(x => x.id === id ? { ...x, state: approve ? 'approved' : 'rejected', memberId: approve ? memberId : undefined } : x), people: approve ? [...d.people, personFromApplication(a, memberId)] : d.people, log: [`Solicitud ${approve ? 'aprobada' : 'rechazada'}: ${a.name}`, ...d.log] })); }
  async function copyInvite(id: string) { const url = new URL(location.href); url.search = ''; url.hash = ''; url.searchParams.set('invite', id); try { await navigator.clipboard.writeText(url.href); toast(tr('Enlace copiado. Válido solo en esta demo local.', 'Link copied. Valid only in this local demo.')); } catch { open('link', url.href); } }
  function external(url: string, label: ReactNode) { const href = safeUrl(url); return href ? <a className="external" href={href} target="_blank" rel="noopener noreferrer">{label}<ArrowUpRight size={15}/></a> : null; }
  function statusLabel(status: string) { return ({ todo: tr('Por hacer','To do'), doing: tr('En progreso','In progress'), done: tr('Completada','Done'), pending: tr('Pendiente','Pending'), approved: tr('Aprobada','Approved'), rejected: tr('Rechazada','Rejected'), active: tr('En construcción','Building'), completed: tr('Finalizado','Completed') } as Record<string,string>)[status] || status; }
  const nav = [
    { id: 'home', label: tr('Inicio', 'Overview'), icon: LayoutDashboard },
    { id: 'projects', label: tr('Proyectos', 'Projects'), icon: Layers },
    { id: 'challenges', label: tr('Retos', 'Challenges'), icon: Target },
    { id: 'community', label: tr('Comunidad', 'Community'), icon: MessageSquare },
    { id: 'learning', label: tr('Aprendizaje', 'Learning'), icon: GraduationCap },
    { id: 'members', label: tr('Talento', 'Talent'), icon: Users },
  ];
  const pageTitle = project?.title || nav.find(n => n.id === page)?.label || ({ invites: tr('Invitaciones', 'Invitations'), admin: tr('Administración', 'Administration'), profile: tr('Mi perfil', 'My profile') })[page as 'invites'|'admin'|'profile'];
  const filteredProjects = data.projects.filter(p => `${p.title} ${p.summary} ${p.tags.join(' ')}`.toLowerCase().includes(search.toLowerCase()));
  const myProjects = data.projects.filter(p => p.members.includes(actor));
  const myTasks = myProjects.flatMap(p => p.tasks.filter(t => t.owner === actor && t.status !== 'done').map(t => ({...t, project: p})));
  const activeCount = data.people.filter(p => p.status === 'active').length;

  function projectCard(p: Project) { return <button className="project-card" key={p.id} onClick={() => openProject(p.id)}><div className="card-top"><div className={`project-symbol ${p.id === 'p2' ? 'green' : p.id === 'p3' ? 'orange' : ''}`}><Code2 size={23}/></div><span className={`badge ${p.status === 'completed' ? 'success' : ''}`}><span className="dot"/>{statusLabel(p.status)}</span></div><h3>{p.title}</h3><p>{p.summary}</p><div className="tags">{p.tags.map(t => <span key={t}>{t}</span>)}</div><div className="card-bottom"><div className="avatars">{p.members.slice(0,3).map(id => <span title={name(id)} key={id}>{initials(name(id))}</span>)}</div><span>{p.members.length}/{p.capacity} <Users size={13}/></span><ArrowUpRight size={19}/></div></button>; }
  function empty(title: string, description: string) { return <div className="empty"><Sparkles size={28}/><h3>{title}</h3><p>{description}</p></div>; }
  function sendMessage(e: FormEvent<HTMLFormElement>, forum = false) { e.preventDefault(); if (!enabled || (!forum && !memberOf)) return; const form = e.currentTarget; const text = String(new FormData(form).get('message') || '').trim(); if (!text) return; const message = { id: uid(), author: actor, text, date: new Date().toISOString(), channel }; if (forum) setData(d => ({ ...d, forum: [...d.forum, message] })); else patchProject(project!.id, p => ({ ...p, messages: [...p.messages, message] })); form.reset(); }
  function messages(list: State['forum']) { return <div className="messages">{list.length ? list.map(m => <article className="message" key={m.id}><div className="avatar">{initials(name(m.author))}</div><div><div className="message-meta"><strong>{name(m.author)}</strong><time>{new Date(m.date).toLocaleString(lang === 'es' ? 'es-CO' : 'en-US', { month:'short', day:'numeric', hour:'2-digit', minute:'2-digit' })}</time><button className="icon-button" aria-label={tr('Reportar mensaje','Report message')} onClick={() => open('report', m.id)}><Flag size={13}/></button></div><p>{m.text}</p></div></article>) : empty(tr('Empieza la conversación','Start the conversation'), tr('Comparte avances, preguntas o bloqueos.','Share progress, questions or blockers.'))}</div>; }
  function composer(forum: boolean) { return <form className="composer" onSubmit={e => sendMessage(e, forum)}><input name="message" required maxLength={2000} aria-label={tr('Mensaje','Message')} placeholder={tr('Comparte algo con el equipo…','Share something with the team…')}/><button className="primary" aria-label={tr('Enviar','Send')}><ArrowRight size={18}/></button></form>; }

  function home() { return <>
    <div className="welcome"><div><div className="eyebrow">{tr('TU SIGUIENTE GRAN PASO', 'YOUR NEXT BIG STEP')}</div><h1>{isVisitor ? tr('El talento necesita un lugar para construir.','Talent needs a place to build.') : <>{tr('Hola', 'Hello')}, {me?.name.split(' ')[0]}<span className="welcome-dot">.</span></>}</h1><p>{tr('Conecta con personas que construyen. Aprende haciendo. Lleva tu potencial más lejos.', 'Connect with builders. Learn by doing. Take your potential further.')}</p></div><button className="primary" onClick={() => isVisitor ? open('apply') : open('project')}><Plus size={17}/>{isVisitor ? tr('Solicitar ingreso','Apply to join') : tr('Crear proyecto','Create project')}</button></div>
    <section className="hero"><div className="hero-copy"><span className="badge hero-badge"><Zap size={13}/>{tr('EL PRÓXIMO NÚMERO 1', 'THE NEXT NUMBER ONE')}</span><h2>{tr('Tu potencial,','Your potential,')}<br/><span>{tr('en construcción.','under construction.')}</span></h2><p>{tr('Una comunidad tech para transformar lo que sabes en proyectos que importan. Tu siguiente equipo empieza aquí.', 'A tech community to turn what you know into projects that matter. Your next team starts here.')}</p><button className="light-button" onClick={() => navigate('projects')}>{tr('Explorar proyectos','Explore projects')}<ArrowUpRight size={17}/></button></div><div className="hero-art" aria-hidden="true"><div className="orbital orbit-one"/><div className="orbital orbit-two"/><div className="orbit-core">1<span>next</span></div><span className="orbit-label label-one"><Code2 size={15}/> build</span><span className="orbit-label label-two"><Users size={15}/> connect</span><span className="orbit-label label-three"><Sparkles size={15}/> grow</span></div></section>
    <div className="metrics">{[{ icon: Users, number: activeCount, title: tr('Builders activos','Active builders'), detail: tr('Meta inicial: 30 personas','Initial goal: 30 people') }, { icon: Layers, number: data.projects.filter(p => p.status === 'active').length, title: tr('Proyectos en marcha','Projects underway'), detail: tr('Ideas que se vuelven realidad','Ideas becoming reality') }, { icon: CheckCircle2, number: data.projects.filter(p => p.status === 'completed').length, title: tr('Proyectos culminados','Completed projects'), detail: tr('Resultados, no solo ideas','Results, beyond ideas') }, { icon: GraduationCap, number: data.lessons.filter(l => l.approved).length, title: tr('Recursos para crecer','Resources to grow'), detail: tr('Aprendizaje en comunidad','Learning together') }].map(m => <div className="metric" key={m.title}><m.icon size={18}/><strong>{m.number.toString().padStart(2,'0')}</strong><h4>{m.title}</h4><p>{m.detail}</p></div>)}</div>
    <div className="section-title"><div><h2>{tr('Encuentra tu próximo proyecto','Find your next project')}</h2><p>{tr('Equipos pequeños. Problemas reales. Posibilidades enormes.','Small teams. Real problems. Big possibilities.')}</p></div><button className="text-button" onClick={() => navigate('projects')}>{tr('Ver todos','View all')}<ArrowRight size={16}/></button></div><div className="project-grid">{data.projects.slice(0,3).map(projectCard)}</div>
    <div className="two-columns"><section className="panel"><div className="section-title"><h3>{tr('Tu próximo movimiento','Your next move')}</h3><ListTodo size={18}/></div>{myTasks.length ? myTasks.slice(0,3).map(t => <button className="list-row" key={t.id} onClick={() => openProject(t.project.id)}><Circle size={17}/><div><strong>{t.title}</strong><small>{t.project.title} · {statusLabel(t.status)}</small></div><ChevronRight size={16}/></button>) : <p className="muted">{tr('Explora proyectos y encuentra un equipo al que aportar.','Explore projects and find a team to contribute to.')}</p>}</section><section className="panel accent-panel"><div className="eyebrow">{tr('APRENDEMOS JUNTOS','WE LEARN TOGETHER')}</div><h3>{tr('No tienes que saberlo todo para empezar.','You don’t need to know everything to start.')}</h3><p>{tr('Encuentra recursos y sesiones con mentores para avanzar en tu siguiente desafío.','Find resources and mentor sessions for your next challenge.')}</p><button className="text-button" onClick={() => navigate('learning')}>{tr('Explorar aprendizaje','Explore learning')}<ArrowUpRight size={17}/></button></section></div>
  </>; }
  function projectsPage() { return <><div className="welcome"><div><div className="eyebrow">BUILD TOGETHER</div><h1>{tr('Ideas con equipo.','Ideas with a team.')}</h1><p>{tr('Encuentra un problema que te importe y construye una solución.','Find a problem you care about and build a solution.')}</p></div>{enabled && <button className="primary" onClick={() => open('project')}><Plus size={16}/>{tr('Crear proyecto','Create project')}</button>}</div><div className="filter-bar"><label className="search"><Search size={17}/><input value={search} onChange={e => setSearch(e.target.value)} placeholder={tr('Buscar por proyecto o tecnología','Search projects or technologies')}/></label><span className="muted">{filteredProjects.length} {tr('proyectos','projects')}</span></div><div className="project-grid">{filteredProjects.map(projectCard)}</div>{!filteredProjects.length && empty(tr('Sin resultados','No results'),tr('Prueba con otra tecnología o palabra.','Try a different technology or keyword.'))}</>; }
  function projectPage(p: Project) { const progress = p.tasks.length ? Math.round(p.tasks.filter(t => t.status === 'done').length / p.tasks.length * 100) : 0; return <>
    <button className="text-button back" onClick={() => setProjectId(null)}>← {tr('Todos los proyectos','All projects')}</button><div className="welcome"><div><span className="badge"><span className="dot"/>{statusLabel(p.status)}</span><h1>{p.title}</h1><p>{p.summary}</p><div className="tags">{p.tags.map(t => <span key={t}>{t}</span>)}</div></div><div className="actions">{!isVisitor && !memberOf && enabled && <button className="primary" disabled={p.requests.includes(actor) || p.status === 'completed'} onClick={() => join(p)}>{p.requests.includes(actor) ? tr('Solicitud enviada','Request sent') : tr('Solicitar unirme','Request to join')}<ArrowRight size={16}/></button>}{isVisitor && <button className="primary" onClick={() => open('apply')}>{tr('Unirme a nextONE','Join nextONE')}</button>}{memberOf && p.owner !== actor && !isFounder && <button className="secondary" onClick={() => open('leave',p.id)}><LogOut size={15}/>{tr('Salir del equipo','Leave team')}</button>}</div></div>
    <div className="tabs">{[['overview',tr('Resumen público','Public overview')], ...(memberOf ? [['tasks',tr('Tareas','Tasks')],['chat',tr('Conversaciones','Conversations')],['docs',tr('Documentación','Documentation')],['team',tr('Equipo','Team')]] : [])].map(([id,label]) => <button className={tab===id?'active':''} key={id} onClick={() => setTab(id)}>{label}{id==='team' && p.requests.length>0 && manages && <span className="count">{p.requests.length}</span>}</button>)}</div>
    {tab==='overview' && <div className="detail-grid"><div><section className="panel"><div className="section-title"><h3>{tr('Qué vamos a construir','What we will build')}</h3><Target size={18}/></div><p className="prewrap">{p.scope}</p><h4>{tr('Nuestro factor diferenciador','Our differentiator')}</h4><p>{p.difference}</p></section><section className="panel"><div className="section-title"><h3>{tr('Avances públicos','Public progress')}</h3>{manages && <button className="text-button" onClick={() => open('update',p.id)}><Plus size={15}/>{tr('Publicar','Publish')}</button>}</div>{p.updates.length ? p.updates.map((u,i) => <div className="update" key={i}><span className="badge success">{tr('Avance','Update')} {i+1}</span><p className="prewrap">{u}</p></div>) : <p className="muted">{tr('El equipo aún no ha publicado avances.','The team has not published progress yet.')}</p>}</section></div><aside><section className="panel"><h3>{tr('El equipo','The team')}</h3><div className="person-row"><div className="avatar">{initials(name(p.owner))}</div><div><strong>{name(p.owner)}</strong><small>{tr('Líder del proyecto','Project leader')}</small></div></div><hr/><p>{p.members.length} / {p.capacity} {tr('integrantes','members')}</p><h4>{tr('Roles del proyecto','Project roles')}</h4><div className="tags">{p.roles.map(r => <span key={r}>{r}</span>)}</div>{memberOf && <><h4>{tr('Avance de tareas','Task progress')}</h4><div className="progress"><span style={{width: `${progress}%`}}/></div><small>{progress}%</small></>}{manages && <button className="secondary full" onClick={() => { patchProject(p.id,x=>({...x,status:x.status==='active'?'completed':'active'})); log(`Estado actualizado / ${p.title}`); }}>{p.status==='active'?tr('Marcar finalizado','Mark completed'):tr('Reabrir proyecto','Reopen project')}</button>}</section>{!memberOf && <section className="panel"><Lock size={22}/><h4>{tr('El trabajo ocurre dentro del equipo','Work happens inside the team')}</h4><p>{tr('Las tareas, conversaciones y documentación están disponibles para integrantes aprobados.','Tasks, conversations and documentation are available to approved members.')}</p></section>}</aside></div>}
    {memberOf && tab==='tasks' && <><div className="section-title"><p>{tr('Cada tarea representa un compromiso. Pulsa su estado para avanzar.','Every task is a commitment. Click its status to move it forward.')}</p><button className="primary" onClick={() => open('task',p.id)}><Plus size={16}/>{tr('Nueva tarea','New task')}</button></div><div className="kanban">{(['todo','doing','done'] as const).map(status=><section key={status}><h3><span className={`status-dot ${status}`}/>{statusLabel(status)}<span className="count">{p.tasks.filter(t=>t.status===status).length}</span></h3>{p.tasks.filter(t=>t.status===status).map(t=><article className="task" key={t.id}><small>{tr('Compromiso','Commitment')} · {t.period==='daily'?tr('Diario','Daily'):t.period==='weekly'?tr('Semanal','Weekly'):tr('Mensual','Monthly')}</small><h4>{t.title}</h4><div className="task-bottom"><span className="avatar tiny" title={name(t.owner)}>{initials(name(t.owner))}</span><button className="text-button" onClick={()=>toggleTask(p,t.id)}>{status==='done'?<CheckCircle2 size={17}/>:<ArrowRight size={17}/>}<span className="sr-only">{tr('Cambiar estado','Change status')}</span></button></div></article>)}</section>)}</div></>}
    {memberOf && tab==='chat' && <section className="chat-panel"><aside className="channel-list"><div className="eyebrow">{tr('CANALES DEL EQUIPO','TEAM CHANNELS')}</div>{['general','dev','feedback'].map(c=><button key={c} className={channel===c?'active':''} onClick={()=>setChannel(c)}># {c}<Lock size={12}/></button>)}<hr/><button onClick={()=>toast(tr('Voz integrada pendiente. En la presentación usaremos un enlace de reunión compartido en el canal.','Integrated voice is pending. For the presentation, share a meeting link in the channel.'))}><Radio size={16}/>{tr('Sala de voz','Voice room')}<span className="badge">{tr('Próximamente','Soon')}</span></button></aside><div className="chat-main"><div className="chat-header"># {channel}<span className="muted"><Lock size={13}/>{tr('Privado al equipo','Team private')}</span></div>{messages(p.messages.filter(m=>m.channel===channel))}{composer(false)}</div></section>}
    {memberOf && tab==='docs' && <section className="panel"><div className="section-title"><h3><FileText size={18}/>{tr('Bitácora y alcance','Project log and scope')}</h3><span className="badge">{manages?tr('Puedes editar','Can edit'):tr('Solo lectura','Read only')}</span></div>{manages ? <form onSubmit={e=>{e.preventDefault();patchProject(p.id,x=>({...x,docs:String(new FormData(e.currentTarget).get('docs'))}));toast(tr('Documentación guardada.','Documentation saved.'));}}><textarea className="doc-editor" name="docs" defaultValue={p.docs} key={p.id}/><button className="primary">{tr('Guardar documentación','Save documentation')}</button></form> : <p className="prewrap">{p.docs}</p>}<p className="muted small">{tr('En este MVP el líder edita y el equipo puede leer. Los permisos específicos por rol quedan para la siguiente etapa.','In this MVP the leader edits and the team reads. Role-specific permissions are planned for the next stage.')}</p></section>}
    {memberOf && tab==='team' && <div className="two-columns"><section className="panel"><h3>{tr('Integrantes','Members')}</h3>{p.members.map(id=><div className="person-row" key={id}><div className="avatar">{initials(name(id))}</div><div><strong>{name(id)}</strong><small>{id===p.owner?tr('Líder','Leader'):tr('Colaborador','Contributor')}</small></div>{manages && id!==p.owner && <button className="icon-button" aria-label={tr('Retirar integrante','Remove member')} onClick={()=>open('remove',id)}><LogOut size={15}/></button>}</div>)}{p.exits.length>0 && manages && <><h4>{tr('Registro de salidas','Exit log')}</h4>{p.exits.map((x,i)=><p className="small" key={i}>{name(x.user)}: {x.reason}</p>)}</>}</section><section className="panel"><h3>{tr('Solicitudes de participación','Participation requests')}</h3>{manages ? p.requests.length?p.requests.map(id=><div className="person-row" key={id}><div className="avatar">{initials(name(id))}</div><div><strong>{name(id)}</strong><small>{data.people.find(x=>x.id===id)?.skills.join(' · ')}</small></div><button className="icon-button" aria-label={tr('Aprobar','Approve')} onClick={()=>approveMember(p,id)}><Check size={18}/></button><button className="icon-button" aria-label={tr('Rechazar','Reject')} onClick={()=>patchProject(p.id,x=>({...x,requests:x.requests.filter(r=>r!==id)}))}><X size={18}/></button></div>):<p className="muted">{tr('No hay solicitudes pendientes.','No pending requests.')}</p> : <p className="muted">{tr('El líder gestiona las solicitudes.','The leader manages requests.')}</p>}<hr/><div className="eyebrow"><Sparkles size={14}/>{tr('MATCH DE HABILIDADES · DEMO','SKILL MATCH · DEMO')}</div><p className="small muted">{tr('Coincidencia por etiquetas, sin analizar hojas de vida ni usar IA.','Tag matching, without resume analysis or AI.')}</p>{data.people.filter(person=>!p.members.includes(person.id)&&person.status==='active').map(person=>({person,score:person.skills.filter(s=>p.tags.some(t=>t.toLowerCase()===s.toLowerCase())).length})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).map(({person,score})=><div className="list-row" key={person.id}><div className="avatar">{initials(person.name)}</div><div><strong>{person.name}</strong><small>{score} {tr('habilidades coincidentes','matching skills')}</small></div></div>)}</section></div>}
  </>; }
  function challengesPage() { return <><div className="welcome"><div><div className="eyebrow">SOLVE SOMETHING REAL</div><h1>{tr('Un reto. Muchas posibilidades.','One challenge. Many possibilities.')}</h1><p>{tr('Propón una solución. Encuentra apoyo. Conviértela en un proyecto.','Propose a solution. Find support. Turn it into a project.')}</p></div>{enabled&&<button className="primary" onClick={()=>open('challenge')}><Plus size={16}/>{tr('Publicar reto','Post challenge')}</button>}</div>{data.challenges.map(c=><section className="panel challenge" key={c.id}><div className="section-title"><span className="badge">{c.area}</span><span className="muted small">{tr('Por','By')} {name(c.owner)}</span></div><h2>{c.title}</h2><p>{c.description}</p><div className="section-title"><h4>{tr('Propuestas de solución','Solution proposals')} · {c.solutions.length}</h4>{enabled&&!c.selected&&<button className="secondary" onClick={()=>open('solution',c.id)}><Plus size={15}/>{tr('Proponer solución','Propose solution')}</button>}</div>{c.solutions.map(s=><article className={`solution ${c.selected===s.id?'selected':''}`} key={s.id}><div className="section-title"><strong>{name(s.author)}</strong>{c.selected===s.id?<span className="badge success"><Sparkles size={13}/>{tr('Creador destacado','Featured creator')}</span>:enabled&&(isFounder||c.owner===actor)&&!c.selected&&<button className="text-button" onClick={()=>{const pid=uid();const newProject:Project={id:pid,title:c.title,summary:c.description,scope:s.text,difference:'Solución seleccionada en un reto de nextONE.',tags:[c.area],owner:s.author,members:[s.author],roles:['Producto','Desarrollo'],capacity:3,requests:[],tasks:[],messages:[],docs:s.text,updates:[],exits:[],status:'active'};setData(d=>({...d,projects:[...d.projects,newProject],challenges:d.challenges.map(x=>x.id===c.id?{...x,selected:s.id,projectId:pid}:x)}));toast(tr('Propuesta convertida en proyecto.','Proposal turned into a project.'));}}>{tr('Elegir y crear proyecto','Select and create project')}<ArrowUpRight size={15}/></button>}</div><p>{s.text}</p></article>)}{c.projectId&&<button className="text-button" onClick={()=>openProject(c.projectId!)}>{tr('Ver proyecto resultante','View resulting project')}<ArrowRight size={16}/></button>}</section>)}</>; }
  function learningPage() { return <><div className="welcome"><div><div className="eyebrow">LEARN. BUILD. REPEAT.</div><h1>{tr('Crece con cada proyecto.','Grow with every project.')}</h1><p>{tr('Recursos para aprender a tu ritmo y sesiones para aprender juntos.','Resources at your own pace and sessions to learn together.')}</p></div>{enabled&&<button className="primary" onClick={()=>open('lesson')}><Plus size={16}/>{tr('Proponer recurso','Suggest resource')}</button>}</div><div className="project-grid">{data.lessons.filter(l=>l.approved).map(l=><section className="panel lesson" key={l.id}><div className="lesson-art"><GraduationCap size={42}/><span>nextONE / academy</span></div><span className="badge">{l.category}</span><h3>{l.title}</h3><p>{l.description}</p><div className="person-row"><span className="avatar tiny">{initials(name(l.mentor))}</span><small>{name(l.mentor)}</small></div><div className="small muted"><Clock size={14}/> {l.date?new Date(l.date).toLocaleString(lang==='es'?'es-CO':'en-US'):tr('A tu ritmo / horario por confirmar','Self-paced / schedule to be confirmed')}</div><div className="lesson-actions">{external(l.url,tr('Abrir recurso','Open resource'))}{enabled&&<button className={l.enrolled.includes(actor)?'secondary':'primary'} onClick={()=>setData(d=>({...d,lessons:d.lessons.map(x=>x.id===l.id?{...x,enrolled:x.enrolled.includes(actor)?x.enrolled.filter(i=>i!==actor):[...x.enrolled,actor]}:x)}))}>{l.enrolled.includes(actor)?<Check size={15}/>:<Plus size={15}/>} {l.enrolled.includes(actor)?tr('Inscrito · cancelar','Enrolled · cancel'):tr('Inscribirme','Enroll')}</button>}</div><small className="muted">{l.enrolled.length} {tr('participantes inscritos','enrolled participants')}</small>{enabled&&(isFounder||l.mentor===actor)&&l.enrolled.length>0&&<details><summary>{tr('Registrar asistencia','Record attendance')}</summary>{l.enrolled.map(id=><label className="attendance" key={id}><input type="checkbox" checked={l.attendees.includes(id)} onChange={()=>setData(d=>({...d,lessons:d.lessons.map(x=>x.id===l.id?{...x,attendees:x.attendees.includes(id)?x.attendees.filter(i=>i!==id):[...x.attendees,id]}:x)}))}/>{name(id)}</label>)}</details>}</section>)}</div></>; }
  function communityPage() { return <><div className="welcome"><div><div className="eyebrow">BETTER TOGETHER</div><h1>{tr('Tu comunidad de builders.','Your community of builders.')}</h1><p>{tr('Comparte lo que aprendes. Pregunta lo que necesitas.','Share what you learn. Ask what you need.')}</p></div></div><section className="panel"><div className="chat-header"># {tr('foro-general','general-forum')}<span className="badge success">{tr('Comunidad','Community')}</span></div>{messages(data.forum)}{enabled&&composer(true)}</section></>; }
  function membersPage() { const people=data.people.filter(p=>p.status==='active'&&`${p.name} ${p.skills.join(' ')}`.toLowerCase().includes(search.toLowerCase()));return <><div className="welcome"><div><div className="eyebrow">PEOPLE MAKE IT HAPPEN</div><h1>{tr('El talento está aquí.','The talent is here.')}</h1><p>{tr('Busca habilidades y encuentra a las personas con quienes construir.','Find skills and people to build with.')}</p></div></div><label className="search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder={tr('Buscar personas o habilidades','Search people or skills')}/></label><div className="project-grid space-top">{people.map(person=><section className="panel member-card" key={person.id}><div className="section-title"><div className="avatar large">{initials(person.name)}</div>{person.role==='mentor'&&<span className="badge">{tr('Mentor','Mentor')}</span>}{enabled&&<button className="icon-button" aria-label={tr('Reportar usuario','Report user')} onClick={()=>open('report',person.id)}><Flag size={15}/></button>}</div><h3>{person.name}</h3><p className="member-title">{person.title}</p><p>{person.bio}</p><div className="tags">{person.skills.map(s=><span key={s}>{s}</span>)}</div><small className="muted"><Clock size={13}/> {person.availability} h / {tr('semana','week')}</small><div className="actions">{external(person.portfolio,tr('Portafolio','Portfolio'))}{external(person.linkedin,'LinkedIn')}</div></section>)}</div>{!people.length&&empty(tr('Sin coincidencias','No matches'),tr('Busca otra habilidad.','Try another skill.'))}</>; }
  function invitesPage() { const invites=data.invites.filter(i=>isFounder||i.owner===actor); return <><div className="welcome"><div><div className="eyebrow">GROW WITH INTENTION</div><h1>{tr('Invita al próximo talento.','Invite the next talent.')}</h1><p>{tr('Cada enlace conserva su referente, cupo y ruta de ingreso.','Each link preserves its referrer, quota and admission path.')}</p></div>{isFounder&&<button className="primary" onClick={()=>open('invite')}><Plus size={16}/>{tr('Crear enlace','Create link')}</button>}</div><div className="callout"><Link size={20}/><p>{tr('Demo local: los cupos funcionan en este navegador. Un enlace compartido aún no sincroniza solicitudes entre dispositivos; eso requiere el backend.','Local demo: quotas work in this browser. Shared links do not sync applications between devices yet; that requires the backend.')}</p></div>{invites.map(i=><section className="panel invite" key={i.id}><div><span className="badge">{i.kind==='review'?tr('Requiere revisión','Review required'):tr('Ingreso directo','Direct admission')}</span><h3>{i.label}</h3><p>{name(i.owner)} · {i.kind} · {tr('Vence','Expires')} {new Date(i.expires).toLocaleDateString()}</p><div className="progress"><span style={{width:`${i.used/i.limit*100}%`}}/></div><small>{i.used} / {i.limit} {tr('cupos utilizados','places used')} · {invitationStatus(i)==='available'?tr('Disponible','Available'):tr('No disponible','Unavailable')}</small></div><div className="actions"><button className="secondary" disabled={invitationStatus(i)!=='available'} onClick={()=>copyInvite(i.id)}><Copy size={15}/>{tr('Copiar enlace','Copy link')}</button><button className="text-button" disabled={invitationStatus(i)!=='available'} onClick={()=>{setActor('visitor');open('apply',i.id);}}>{tr('Probar ingreso','Test admission')}<ArrowUpRight size={15}/></button>{isFounder&&!i.revoked&&<button className="icon-button" aria-label={tr('Revocar invitación','Revoke invitation')} onClick={()=>{setData(d=>({...d,invites:d.invites.map(x=>x.id===i.id?{...x,revoked:true}:x)}));log(`Enlace revocado: ${i.label}`);}}><Trash2 size={16}/></button>}</div></section>)}</>; }
  function adminPage() { return <><div className="welcome"><div><div className="eyebrow">COMMUNITY OPERATIONS</div><h1>{tr('Una comunidad con dirección.','A community with direction.')}</h1><p>{tr('Gestiona acceso, contenido y convivencia.','Manage access, content and community standards.')}</p></div><button className="secondary" onClick={()=>open('reset')}>{tr('Restablecer demo','Reset demo')}</button></div><div className="two-columns"><section className="panel"><h3>{tr('Solicitudes de ingreso','Admission requests')}</h3>{data.applications.length?data.applications.map(a=><div className="application" key={a.id}><div className="section-title"><strong>{a.name}</strong><span className="badge">{statusLabel(a.state)}</span></div><p>{a.bio}</p><small>{a.email} · {a.skills}</small><p className="muted small">{a.source}</p><div className="actions">{external(a.portfolio,tr('Portafolio','Portfolio'))}{external(a.linkedin,'LinkedIn')}{external(a.cv,tr('Hoja de vida','Resume'))}</div>{a.state==='pending'&&<div className="actions space-top"><button className="primary" onClick={()=>decideApplication(a.id,true)}>{tr('Aprobar','Approve')}</button><button className="secondary" onClick={()=>decideApplication(a.id,false)}>{tr('Rechazar','Reject')}</button></div>}</div>):<p className="muted">{tr('Prueba una solicitud desde la vista de visitante.','Try an application from the visitor view.')}</p>}</section><section className="panel"><h3>{tr('Filtro de recursos','Resource review')}</h3>{data.lessons.filter(l=>!l.approved).length?data.lessons.filter(l=>!l.approved).map(l=><div className="application" key={l.id}><strong>{l.title}</strong><p>{l.description}</p>{external(l.url,tr('Revisar enlace','Review link'))}<div className="actions"><button className="primary" onClick={()=>setData(d=>({...d,lessons:d.lessons.map(x=>x.id===l.id?{...x,approved:true}:x)}))}>{tr('Publicar','Publish')}</button><button className="secondary" onClick={()=>setData(d=>({...d,lessons:d.lessons.filter(x=>x.id!==l.id)}))}>{tr('Descartar','Dismiss')}</button></div></div>):<p className="muted">{tr('No hay recursos pendientes.','No pending resources.')}</p>}<hr/><h3>{tr('Reportes de convivencia','Community reports')}</h3>{data.reports.length?data.reports.map(r=><div className="application" key={r.id}><strong>{r.target}</strong><p>{r.reason}</p><small>{tr('Reportado por','Reported by')} {name(r.author)}</small>{r.state==='open'?<button className="secondary full" onClick={()=>open('resolve',r.id)}>{tr('Revisar y resolver','Review and resolve')}</button>:<p className="badge">{r.decision}</p>}</div>):<p className="muted">{tr('No hay reportes.','No reports.')}</p>}</section></div><section className="panel"><div className="section-title"><h3>{tr('Miembros y procedencia','Members and attribution')}</h3><span className="badge">{data.people.length}</span></div><div className="table-scroll"><table><thead><tr><th>{tr('Persona','Person')}</th><th>{tr('Origen','Source')}</th><th>{tr('Rol','Role')}</th><th>{tr('Estado','Status')}</th></tr></thead><tbody>{data.people.map(person=><tr key={person.id}><td>{person.name}</td><td>{person.source}</td><td>{person.role==='founder'?tr('Fundador','Founder'):<select aria-label={tr('Rol del usuario','User role')} value={person.role} onChange={e=>{const role=e.target.value as Person['role'];setData(d=>({...d,people:d.people.map(p=>p.id===person.id?{...p,role}:p)}));log(`Rol actualizado: ${person.name} / ${role}`);}}><option value="member">{tr('Miembro','Member')}</option><option value="mentor">{tr('Mentor','Mentor')}</option></select>}</td><td>{person.role==='founder'?tr('Activo','Active'):<button className="text-button" onClick={()=>open('suspend',person.id)}>{person.status==='active'?tr('Activo · suspender','Active · suspend'):tr('Suspendido · revisar','Suspended · review')}</button>}</td></tr>)}</tbody></table></div></section><section className="panel"><h3>{tr('Bitácora administrativa','Administration log')}</h3>{data.log.slice(0,12).map((l,i)=><p className="small muted" key={i}>{l}</p>)}</section></>; }
  function profilePage() { return <><div className="welcome"><div><div className="eyebrow">YOUR BUILDER IDENTITY</div><h1>{tr('Muestra lo que puedes aportar.','Show what you can contribute.')}</h1><p>{tr('Tu perfil conecta habilidades, intereses y disponibilidad.','Your profile connects skills, interests and availability.')}</p></div><button className="primary" onClick={()=>open('profile')}>{tr('Editar perfil','Edit profile')}</button></div><section className="panel profile"><div className="avatar large">{initials(me!.name)}</div><h2>{me!.name}</h2><h4>{me!.title}</h4><p>{me!.bio}</p><div className="tags">{me!.skills.map(s=><span key={s}>{s}</span>)}</div><p>{me!.availability} h / {tr('semana','week')}</p><div className="actions">{external(me!.portfolio,tr('Portafolio','Portfolio'))}{external(me!.linkedin,'LinkedIn')}</div></section></>; }

  function modalConfig(): { title: string; description?: string; fields: Field[]; submit?: string } {
    const field = (name:string,label:string,type='text',required=true,value?:string|number):Field=>({name,label,type,required,value});
    switch(modal?.kind) {
      case 'project': return {title:tr('Dale forma a tu proyecto','Shape your project'),description:tr('Describe el problema y tu propuesta. El asistente demo te ayuda a revisar el alcance.','Describe the problem and proposal. The demo assistant helps review scope.'),fields:[field('title',tr('Nombre del proyecto','Project name')),field('summary',tr('Problema y solución (mínimo 40 caracteres)','Problem and solution (at least 40 characters)'),'textarea'),field('scope',tr('Alcance y entregable','Scope and deliverable'),'textarea'),field('difference',tr('Factor diferenciador (mínimo 20 caracteres)','Differentiator (at least 20 characters)'),'textarea'),field('tags',tr('Tecnologías, separadas por comas','Technologies, comma separated')),field('roles',tr('Roles necesarios, separados por comas','Required roles, comma separated')),{...field('capacity',tr('Integrantes, incluido el líder','Members, including the leader'),'number',true,3),min:1,max:20}],submit:tr('Crear proyecto demo','Create demo project')};
      case 'task': return {title:tr('Un nuevo compromiso','A new commitment'),fields:[field('title',tr('Qué debemos hacer','What we need to do')),{name:'owner',label:tr('Responsable','Owner'),options:project!.members.map(id=>({value:id,label:name(id)}))},{name:'period',label:tr('Periodicidad','Frequency'),options:[{value:'daily',label:tr('Diaria','Daily')},{value:'weekly',label:tr('Semanal','Weekly')},{value:'monthly',label:tr('Mensual','Monthly')}]}]};
      case 'update': return {title:tr('Publicar un avance','Publish an update'),description:tr('Este texto será visible en el perfil público del proyecto. No incluyas información privada.','This text will appear on the public project page. Do not include private information.'),fields:[field('text',tr('Avance del proyecto','Project progress'),'textarea')]};
      case 'challenge': return {title:tr('Un problema que merece solución','A problem worth solving'),fields:[field('title',tr('Título del reto','Challenge title')),field('area',tr('Área','Area')),field('description',tr('Problema y resultado esperado','Problem and expected result'),'textarea')]};
      case 'solution': return {title:tr('Tu propuesta de solución','Your solution proposal'),fields:[field('text',tr('Explica cómo lo resolverías','Explain how you would solve it'),'textarea')]};
      case 'report': return {title:tr('Reportar una situación','Report a concern'),description:tr('Los reportes se revisan antes de actuar. Un reporte deliberadamente falso puede resultar en suspensión; uno no comprobado no se considera falso automáticamente.','Reports are reviewed before action. Intentionally false reports may lead to suspension; unsubstantiated reports are not automatically false.'),fields:[field('reason',tr('Qué ocurrió y qué evidencia existe','What happened and what evidence exists'),'textarea')]};
      case 'resolve': return {title:tr('Resolver reporte','Resolve report'),fields:[field('decision',tr('Decisión y justificación','Decision and rationale'),'textarea')]};
      case 'remove': case 'leave': return {title:modal.kind==='remove'?tr('Retirar integrante','Remove member'):tr('Salir del proyecto','Leave project'),description:tr('La salida queda registrada y no suspende al usuario de la comunidad.','The exit is recorded and does not suspend community membership.'),fields:[field('reason',tr('Motivo de salida','Reason for leaving'),'textarea')]};
      case 'suspend': { const person=data.people.find(p=>p.id===modal.id)!;return {title:person.status==='active'?tr('Suspender usuario','Suspend user'):tr('Restablecer acceso','Restore access'),description:person.name,fields:[field('reason',tr('Motivo de la decisión','Reason for the decision'),'textarea')]}; }
      case 'lesson': return {title:tr('Comparte una oportunidad de aprender','Share a learning opportunity'),description:tr('El recurso pasa por revisión antes de publicarse.','The resource is reviewed before publication.'),fields:[field('title',tr('Título','Title')),{name:'category',label:tr('Tipo','Type'),options:[{value:'Recurso',label:tr('Recurso','Resource')},{value:'Ruta autodidacta',label:tr('Ruta autodidacta','Self-paced path')},{value:'Sesión en vivo',label:tr('Sesión en vivo','Live session')}]},field('description',tr('Descripción','Description'),'textarea'),field('url',tr('Enlace al recurso o reunión','Resource or meeting link'),'url',false),field('date',tr('Fecha de la sesión (opcional)','Session date (optional)'),'datetime-local',false)]};
      case 'invite': return {title:tr('Crear ruta de ingreso','Create admission path'),fields:[field('label',tr('Nombre del enlace o cohorte','Link or cohort name')),{name:'kind',label:tr('Tipo de acceso','Admission type'),options:[{value:'mentor',label:tr('Mentor · directo','Mentor · direct')},{value:'makers',label:tr('Makers · directo','Makers · direct')},{value:'founder',label:tr('Fundador · directo','Founder · direct')},{value:'review',label:tr('Solicitud · revisión','Application · review')}]},{name:'owner',label:tr('Responsable','Owner'),options:data.people.filter(p=>p.role==='mentor'||p.role==='founder').map(p=>({value:p.id,label:p.name}))},{...field('limit',tr('Cupo de invitaciones','Invitation quota'),'number',true,5),min:1,max:1000},field('expires',tr('Fecha de vencimiento','Expiration date'),'date') ]};
      case 'apply': return {title:tr('Tu siguiente paso empieza aquí','Your next step starts here'),description:tr('Esta es una solicitud de demostración. Usa datos ficticios; no cargues un CV real.','This is a demo application. Use fictional details; do not upload a real resume.'),fields:[field('name',tr('Nombre completo','Full name')),field('email',tr('Correo','Email'),'email'),field('skills',tr('Habilidades técnicas, separadas por comas','Technical skills, comma separated')),field('portfolio',tr('Portafolio o GitHub','Portfolio or GitHub'),'url'),field('linkedin','LinkedIn','url'),field('cv',tr('Enlace a hoja de vida (opcional en demo)','Resume link (optional in demo)'),'url',false),field('bio',tr('Qué te gustaría aportar','What you would like to contribute'),'textarea'),field('invite',tr('Código de invitación (opcional)','Invitation code (optional)'),'text',false,modal.id||'')],submit:tr('Enviar solicitud demo','Submit demo application')};
      case 'profile': return {title:tr('Tu perfil técnico','Your technical profile'),fields:[field('name',tr('Nombre','Name'),'text',true,me!.name),field('title',tr('Especialidad','Specialty'),'text',true,me!.title),field('bio',tr('Presentación','About you'),'textarea',true,me!.bio),field('skills',tr('Habilidades, separadas por comas','Skills, comma separated'),'text',true,me!.skills.join(', ')),field('portfolio',tr('Portafolio','Portfolio'),'url',false,me!.portfolio),field('linkedin','LinkedIn','url',false,me!.linkedin),{...field('availability',tr('Horas disponibles por semana','Available hours per week'),'number',true,me!.availability),min:0,max:80}]};
      case 'reset': return {title:tr('Restablecer la demostración','Reset the demonstration'),description:tr('Se borrarán los cambios de este navegador y se restaurarán los ejemplos. Esta acción no se puede deshacer.','Changes in this browser will be deleted and examples restored. This action cannot be undone.'),fields:[],submit:tr('Restablecer datos demo','Reset demo data')};
      case 'link': return {title:tr('Enlace de invitación','Invitation link'),description:modal.id,fields:[],submit:tr('Cerrar','Close')};
      default: return {title:'',fields:[]};
    }
  }
  function submitModal(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); if (!modal) return;
    const form = new FormData(e.currentTarget); const value=(key:string)=>String(form.get(key)||'').trim();
    const list=(key:string)=>[...new Set(value(key).split(',').map(s=>s.trim()).filter(Boolean))];
    if (!['apply','link','reset'].includes(modal.kind)&&!enabled) return;
    switch(modal.kind) {
      case 'project': {const review=reviewProject(value('title'),value('summary'),value('difference'),data.projects);if(!review.ready)return toast(tr('Completa la descripción y el factor diferenciador con más detalle.','Add more detail to the description and differentiator.'));const p:Project={id:uid(),title:value('title'),summary:value('summary'),scope:value('scope'),difference:value('difference'),tags:list('tags'),roles:list('roles'),capacity:Number(value('capacity')),owner:actor,members:[actor],requests:[],tasks:[],messages:[],docs:value('scope'),updates:[],exits:[],status:'active'};setData(d=>({...d,projects:[...d.projects,p]}));openProject(p.id);break;}
      case 'task': if(project&&memberOf)patchProject(project.id,p=>({...p,tasks:[...p.tasks,{id:uid(),title:value('title'),owner:value('owner'),period:value('period'),status:'todo'}]}));break;
      case 'update': if(project&&manages)patchProject(project.id,p=>({...p,updates:[...p.updates,value('text')]}));break;
      case 'challenge': setData(d=>({...d,challenges:[...d.challenges,{id:uid(),title:value('title'),area:value('area'),description:value('description'),owner:actor,solutions:[]}]}));break;
      case 'solution': setData(d=>({...d,challenges:d.challenges.map(c=>c.id===modal.id&&!c.selected?{...c,solutions:[...c.solutions,{id:uid(),author:actor,text:value('text')}]}:c)}));break;
      case 'report':setData(d=>({...d,reports:[...d.reports,{id:uid(),author:actor,target:modal.id||'',reason:value('reason'),state:'open',decision:''}]}));break;
      case 'resolve':if(isFounder){setData(d=>({...d,reports:d.reports.map(r=>r.id===modal.id?{...r,state:'closed',decision:value('decision')}:r)}));log(`Reporte resuelto: ${value('decision')}`);}break;
      case 'leave':case 'remove':if(project&&memberOf&&(modal.kind==='leave'||manages)){const target=modal.kind==='leave'?actor:modal.id!;if(target===project.owner)return toast(tr('El líder no puede salir sin transferir el proyecto.','The leader cannot leave without transferring the project.'));patchProject(project.id,p=>({...p,members:p.members.filter(id=>id!==target),exits:[...p.exits,{user:target,reason:value('reason')}]}));if(modal.kind==='leave')setTab('overview');log(`Salida de ${name(target)} / ${project.title}: ${value('reason')}`);}break;
      case 'suspend':if(isFounder){setData(d=>({...d,people:d.people.map(p=>p.id===modal.id&&p.role!=='founder'?{...p,status:p.status==='active'?'suspended':'active'}:p)}));log(`Acceso revisado: ${name(modal.id!)} / ${value('reason')}`);}break;
      case 'lesson':setData(d=>({...d,lessons:[...d.lessons,{id:uid(),title:value('title'),category:value('category'),mentor:actor,description:value('description'),url:value('url'),date:value('date')?new Date(value('date')).toISOString():'',enrolled:[],attendees:[],approved:false}]}));break;
      case 'invite':if(isFounder){if(new Date(value('expires')+'T23:59:59').getTime()<=Date.now())return toast(tr('Selecciona una fecha futura.','Choose a future date.'));setData(d=>({...d,invites:[...d.invites,{id:uid(),label:value('label'),kind:value('kind') as State['invites'][number]['kind'],owner:value('owner'),limit:Number(value('limit')),used:0,expires:new Date(value('expires')+'T23:59:59').toISOString(),revoked:false}]}));}break;
      case 'apply': {const a:Application={id:uid(),name:value('name'),email:value('email'),skills:value('skills'),portfolio:value('portfolio'),linkedin:value('linkedin'),cv:value('cv'),bio:value('bio'),invite:value('invite'),source:'',state:'pending'};try{const next=submitApplication(data,a);setData(next);const saved=next.applications.find(x=>x.id===a.id)!;setAdmission(saved.state==='approved'?tr('Ingreso directo aprobado en la demo. Ya puedes explorar como nuevo miembro.','Direct admission approved in the demo. You can now explore as a new member.'):tr('Solicitud recibida. Puedes revisarla desde el panel del fundador.','Application received. Review it from the founder panel.'));if(saved.memberId){setActor(saved.memberId);navigate('home');}return;}catch(error){return toast(error instanceof Error&&error.message==='duplicate'?tr('Ya existe una solicitud para este correo.','An application for this email already exists.'):tr('La invitación es inválida, venció, fue revocada o agotó sus cupos.','The invitation is invalid, expired, revoked or full.'));}}
      case 'profile':setData(d=>({...d,people:d.people.map(p=>p.id===actor?{...p,name:value('name'),title:value('title'),bio:value('bio'),skills:list('skills'),portfolio:value('portfolio'),linkedin:value('linkedin'),availability:Number(value('availability'))}:p)}));break;
      case 'reset':if(isFounder){setData(structuredClone(seed));setActor('you');navigate('home');}break;
    }
    setModal(null);toast(tr('Cambio guardado en la demo.','Change saved in the demo.'));
  }
  const config = modalConfig();
  const assessment = reviewProject(assistant.title,assistant.summary,assistant.difference,data.projects);
  const restricted = isVisitor && !['home','projects'].includes(page);
  return <div className="app"><aside className={`sidebar ${mobile?'mobile-open':''}`}><button className="brand" onClick={()=>navigate('home')} aria-label="nextONE home"><span className="brand-icon">n<span>↗</span></span><span>next<strong>ONE</strong><small>BUILD YOUR NEXT.</small></span></button><button className="mobile-close icon-button" aria-label={tr('Cerrar menú','Close menu')} onClick={()=>setMobile(false)}><X/></button><div className="workspace-tag"><span className="dot"/>{tr('Comunidad tech','Tech community')}<span className="badge">PILOT</span></div><div className="nav-label">WORKSPACE</div><nav>{nav.filter(n=>!isVisitor||['home','projects'].includes(n.id)).map(n=><button key={n.id} className={page===n.id?'active':''} onClick={()=>navigate(n.id as Page)}><n.icon size={19}/>{n.label}{n.id==='projects'&&<span className="nav-count">{data.projects.length}</span>}</button>)}</nav>{(isFounder||isMentor)&&<><div className="nav-label">{tr('GESTIÓN','MANAGEMENT')}</div><nav><button className={page==='invites'?'active':''} onClick={()=>navigate('invites')}><Link size={19}/>{tr('Invitaciones','Invitations')}</button>{isFounder&&<button className={page==='admin'?'active':''} onClick={()=>navigate('admin')}><Shield size={19}/>{tr('Administración','Administration')}{data.applications.filter(a=>a.state==='pending').length>0&&<span className="nav-count">{data.applications.filter(a=>a.state==='pending').length}</span>}</button>}</nav></>}
    <div className="sidebar-bottom"><div className="sidebar-note"><Sparkles size={20}/><strong>{tr('Construye tu siguiente versión.','Build your next version.')}</strong><p>{tr('El próximo número 1 puede ser cualquiera. Puede ser tú.','The next number one could be anyone. It could be you.')}</p></div><button className="user-switch" onClick={()=>isVisitor?open('apply'):navigate('profile')}><div className="avatar">{isVisitor?'?':initials(me?.name||'Demo')}</div><div><strong>{isVisitor?tr('Visitante','Visitor'):me?.name}</strong><small>{isVisitor?tr('Explora nextONE','Explore nextONE'):me?.role==='founder'?tr('Fundador','Founder'):me?.role==='mentor'?'Mentor':tr('Miembro','Member')}</small></div><Settings size={16}/></button></div></aside>{mobile&&<button className="sidebar-scrim" aria-label={tr('Cerrar menú','Close menu')} onClick={()=>setMobile(false)}/>}
    <div className="main-shell"><header className="topbar"><button className="icon-button mobile-menu" aria-label={tr('Abrir menú','Open menu')} onClick={()=>setMobile(true)}><Menu size={21}/></button><div className="breadcrumb">Workspace <ChevronRight size={13}/><strong>{pageTitle}</strong></div><div className="topbar-actions"><label className="demo-role"><span>DEMO</span><select aria-label={tr('Explorar como','Explore as')} value={actor} onChange={e=>{setActor(e.target.value);navigate('home');setTab('overview');setModal(null);}}>{data.people.map(p=><option key={p.id} value={p.id}>{p.name} · {p.role==='founder'?tr('Fundador','Founder'):p.role==='mentor'?'Mentor':tr('Miembro','Member')}</option>)}<option value="visitor">{tr('Visitante','Visitor')}</option></select></label><button className="icon-button lang-button" onClick={()=>setLang(lang==='es'?'en':'es')} aria-label={tr('Cambiar a inglés','Switch to Spanish')}><Globe size={15}/>{lang.toUpperCase()}</button><button className="icon-button" aria-label={tr('Cambiar tema','Switch theme')} onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={19}/>:<Moon size={19}/>}</button><select className="accent-select" aria-label={tr('Color de acento','Accent color')} value={accent} onChange={e=>setAccent(e.target.value)}><option value="violet">{tr('Violeta','Violet')}</option><option value="mint">{tr('Menta','Mint')}</option><option value="blue">{tr('Azul','Blue')}</option></select></div></header>
    <div className="demo-banner"><span className="dot"/><span>{tr('Piloto personal · datos ficticios guardados en este navegador · sin IA externa ni conexión multiusuario','Personal pilot · fictional data saved in this browser · no external AI or multi-user connection')}</span></div>{persistenceError&&<div className="callout">{tr('No fue posible guardar los cambios. Se perderán al recargar este navegador.','Changes could not be saved. They will be lost on reload.')}</div>}
    <main>{me?.status==='suspended'?empty(tr('Acceso suspendido','Access suspended'),tr('El fundador puede revisar la decisión desde administración.','The founder can review the decision in administration.')):restricted?empty(tr('Un espacio para miembros','A space for members'),tr('Solicita tu ingreso para participar.','Apply to join and participate.')):page==='admin'&&!isFounder?empty(tr('Acceso restringido','Restricted access'),tr('Solo administración.','Administration only.')):page==='invites'&&!isFounder&&!isMentor?empty(tr('Acceso restringido','Restricted access'),tr('Solo referentes autorizados.','Authorized referrers only.')):project?projectPage(project):page==='home'?home():page==='projects'?projectsPage():page==='challenges'?challengesPage():page==='community'?communityPage():page==='learning'?learningPage():page==='members'?membersPage():page==='invites'?invitesPage():page==='admin'?adminPage():me?profilePage():null}</main><footer>nextONE <span>·</span> {tr('El próximo número 1.','The next number one.')}<small>{tr('Iniciativa independiente · alianza con Makers por explorar','Independent initiative · potential Makers alliance')}</small></footer></div>
    {notice&&<div className="toast" role="status"><CheckCircle2 size={18}/>{notice}<button className="icon-button" aria-label={tr('Cerrar','Close')} onClick={()=>setNotice('')}><X size={15}/></button></div>}
    {modal&&<div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)setModal(null);}}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="section-title"><h2 id="modal-title">{config.title}</h2><button className="icon-button" aria-label={tr('Cerrar','Close')} onClick={()=>setModal(null)}><X size={21}/></button></div>{config.description&&<p className="muted">{config.description}</p>}{admission?<div className="admission-success"><CheckCircle2 size={38}/><h3>{admission}</h3><button className="primary" onClick={()=>setModal(null)}>{tr('Continuar','Continue')}</button></div>:<form onSubmit={submitModal}>{config.fields.map((f,index)=><label className="field" key={f.name}>{f.label}{f.required&&<span> *</span>}{f.options?<select name={f.name} defaultValue={String(f.value||f.options[0]?.value)}>{f.options.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select>:f.type==='textarea'?<textarea autoFocus={index===0} required={f.required} name={f.name} defaultValue={f.value} maxLength={6000} onChange={e=>{if(['title','summary','difference'].includes(f.name))setAssistant(a=>({...a,[f.name]:e.target.value}));setAssistantResult(false);}}/>:<input autoFocus={index===0} name={f.name} type={f.type||'text'} required={f.required} defaultValue={f.value} min={f.min} max={f.max} maxLength={500} onChange={e=>{if(['title','summary','difference'].includes(f.name))setAssistant(a=>({...a,[f.name]:e.target.value}));setAssistantResult(false);}}/>}</label>)}{modal.kind==='project'&&<div className="assistant"><div className="section-title"><strong><Sparkles size={16}/> nextONE Copilot</strong><span className="badge">{tr('DEMO · SIN IA','DEMO · NO AI')}</span></div><p>{tr('Explora el flujo del futuro asistente. Esta versión usa reglas simples y coincidencias de palabras; no aprueba con IA ni verifica originalidad.','Explore the future assistant workflow. This version uses simple rules and word matches; it does not approve with AI or verify originality.')}</p><button type="button" className="secondary" onClick={()=>setAssistantResult(true)}>{tr('Revisar propuesta demo','Review demo proposal')}<Sparkles size={15}/></button>{assistantResult&&<div className="assistant-result"><strong>{assessment.ready?tr('Descripción lista para crear un borrador','Description ready for a draft'):tr('Completa el problema y la diferenciación','Complete the problem and differentiator')}</strong><p>{tr('Equipo orientativo','Suggested team')}: {assessment.teamSize} {tr('personas. Ajusta el cupo según los roles y el alcance.','people. Adjust capacity to roles and scope.')}</p>{assessment.similar.length?<><p>{tr('Proyectos con palabras similares; revisa su enfoque:','Projects with similar wording; review their approach:')}</p>{assessment.similar.map(x=><div key={x.project.id} className="badge">{x.project.title}</div>)}</>:<p>{tr('No encontramos coincidencias con esta regla. Esto no garantiza que el proyecto sea original.','No matches found with this rule. This does not guarantee originality.')}</p>}</div>}</div>}<div className="modal-actions"><button type="button" className="secondary" onClick={()=>setModal(null)}>{tr('Cancelar','Cancel')}</button><button className="primary">{config.submit||tr('Guardar','Save')}<ArrowRight size={15}/></button></div></form>}</section></div>}
  </div>;
}
